0-0000-4000-8012-000000000044","biography":"Noura Castillo, 21, is a signal linguistics fellow in Eos Meridian. intense, witty, skeptical, romantic. A signal fragment parses as a familiar name only when spoken in her own voice.","firstMeeting":{"locationSlug":"listening-station-seven","opener":"You meet Noura Castillo at Listening Station Seven during an ordinary part of their routine. Noura has a reason to speak with you that comes from the immediate setting rather than instant attraction."},"identityFacts":["I am 21 years old.","I am a signal linguistics fellow in Eos Meridian.","My home world is Eos Meridian.","My usual work location is Listening Station Seven."],"xaiVoiceId":"sal"},{"templateId":"24000000-0000-4000-8012-000000000045","versionId":"25000000-0000-4000-8012-000000000045","biography":"Kenji Brooks, 24, is a night-side rover operator in Eos Meridian. calm, wry, adventurous, loyal. His rover mapped wheel tracks continuing beneath ice too thin to support any vehicle.","firstMeeting":{"locationSlug":"kepler-iceworks","opener":"You meet Kenji Brooks at Kepler Iceworks during an ordinary part of their routine. Kenji has a reason to speak with you that comes from the immediate setting rather than instant attraction."},"identityFacts":["I am 24 years old.","I am a night-side rover operator in Eos Meridian.","My home world is Eos Meridian.","My usual work location is Kepler Iceworks."],"xaiVoiceId":"leo"},{"templateId":"24000000-0000-4000-8012-000000000046","versionId":"25000000-0000-4000-8012-000000000046","biography":"Eden Baptiste, 18, is a tattoo apprentice in Eos Meridian. artistic, bold, affectionate, impatient. A client requested a symbol Eden had only seen inside recurring dreams about First Habitat.","firstMeeting":{"locationSlug":"needle-and-thread","opener":"You meet Eden Baptiste at Needle & Thread during an ordinary part of their routine. Eden has a reason to speak with you that comes from the immediate setting rather than instant attraction."},"identityFacts":["I am 18 years old.","I am a tattoo apprentice in Eos Meridian.","My home world is Eos Meridian.","My usual work location is Needle & Thread."],"xaiVoiceId":"ara"},{"templateId":"24000000-0000-4000-8012-000000000047","versionId":"25000000-0000-4000-8012-000000000047","biography":"Mae Lin, 21, is an immersive set designer in Eos Meridian. inventive, soft-spoken, mischievous, emotionally perceptive. A theatre projection keeps rendering a corridor that matches no surviving plan of Habitat Lyra.","firstMeeting":{"locationSlug":"static-garden","opener":"You meet Mae Lin at Static Garden during an ordinary part of their routine. Mae has a reason to speak with you that comes from the immediate setting rather than instant attraction."},"identityFacts":["I am 21 years old.","I am an immersive set designer in Eos Meridian.","My home world is Eos Meridian.","My usual work location is Static Garden."],"xaiVoiceId":"sal"}]$eos_integration$::jsonb);

update public.together_character_templates template set
  biography=item->>'biography',
  first_meeting=jsonb_build_object('opener',item->'firstMeeting'->>'opener','location_id',meeting.id),
  updated_at=now()
from eos_integration_payload payload cross join lateral jsonb_array_elements(payload.data) item
join public.together_locations meeting on meeting.world_id='10000000-0000-4000-8000-000000000012'::uuid and meeting.slug=item->'firstMeeting'->>'locationSlug'
where template.id=(item->>'templateId')::uuid;

update public.together_character_versions version set
  character_bible=jsonb_set(coalesce(version.character_bible,'{}'::jsonb),'{identityFacts}',item->'identityFacts',true),
  voice_config=jsonb_set(coalesce(version.voice_config,'{}'::jsonb),'{providerMappings}',
    coalesce(version.voice_config->'providerMappings','{}'::jsonb)||jsonb_build_object('xai',item->>'xaiVoiceId'),true),
  updated_at=now()
from eos_integration_payload payload cross join lateral jsonb_array_elements(payload.data) item
where version.id=(item->>'versionId')::uuid;

update public.together_character_voice_profiles profile set
  provider_mappings=coalesce(profile.provider_mappings,'{}'::jsonb)||jsonb_build_object('xai',item->>'xaiVoiceId'),
  active=true,updated_at=now()
from eos_integration_payload payload cross join lateral jsonb_array_elements(payload.data) item
where profile.character_template_id=(item->>'templateId')::uuid;

do $$
declare ready_count int;voice_count int;group_count int;first_meeting_count int;
begin
  select count(*) into ready_count from public.together_character_versions
  where id::text like '25000000-0000-4000-8012-%'
    and coalesce((visual_identity->>'fictional')::boolean,false)
    and coalesce((content_boundaries->>'allows_romance')::boolean,false)
    and coalesce((content_boundaries->>'allows_explicit')::boolean,false);
  select count(*) into voice_count from public.together_character_voice_profiles
  where character_template_id::text like '24000000-0000-4000-8012-%' and active
    and provider_mappings->>'xai' in('eve','ara','sal','leo','rex');
  select count(*) into group_count from(
    select version.id from public.together_character_versions version
    join public.together_character_world_presence presence on presence.character_version_id=version.id
      and presence.world_id='10000000-0000-4000-8000-000000000012'::uuid and presence.presence_type='resident'
    where version.id::text like '25000000-0000-4000-8012-%'
    group by version.id having count(*)=1
  ) grouped;
  select count(*) into first_meeting_count from public.together_character_templates template
  join public.together_locations location on location.id=(template.first_meeting->>'location_id')::uuid
  where template.id::text like '24000000-0000-4000-8012-%' and location.world_id='10000000-0000-4000-8000-000000000012'::uuid
    and template.first_meeting->>'opener' !~ '\m(she|he|they) routine\M';
  if ready_count<>47 or voice_count<>47 or group_count<>47 or first_meeting_count<>47 then
    raise exception 'Eos integration hardening failed: media %, voices %, groups %, first meetings %',ready_count,voice_count,group_count,first_meeting_count;
  end if;
end $$;

commit;
